CREATE TABLE oauth_client_flows(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),session_hash TEXT NOT NULL,state_hash TEXT NOT NULL UNIQUE,verifier TEXT NOT NULL,client_id TEXT NOT NULL REFERENCES mcp_clients(id),resource TEXT NOT NULL,issuer TEXT NOT NULL,redirect_uri TEXT NOT NULL,scopes TEXT NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER,status TEXT NOT NULL CHECK(status IN ('pending','complete','denied','cancelled','failed')),token_id TEXT REFERENCES mcp_access_tokens(id));
CREATE TABLE human_review_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,proposal_id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL,actor_id TEXT NOT NULL,decision TEXT NOT NULL,proposal_digest TEXT NOT NULL,review_digest TEXT NOT NULL,base_revision INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER human_review_audit_no_update BEFORE UPDATE ON human_review_audit BEGIN SELECT RAISE(ABORT,'immutable_review_audit'); END;
CREATE TRIGGER human_review_audit_no_delete BEFORE DELETE ON human_review_audit BEGIN SELECT RAISE(ABORT,'immutable_review_audit'); END;
CREATE TABLE proposal_decision_log(id INTEGER PRIMARY KEY AUTOINCREMENT,proposal_id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL,actor_id TEXT NOT NULL,decision TEXT NOT NULL,digest TEXT NOT NULL,base_revision INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER proposal_decision_log_no_update BEFORE UPDATE ON proposal_decision_log BEGIN SELECT RAISE(ABORT,'immutable_decision_log'); END;
CREATE TRIGGER proposal_decision_log_no_delete BEFORE DELETE ON proposal_decision_log BEGIN SELECT RAISE(ABORT,'immutable_decision_log'); END;
CREATE TRIGGER proposal_decision_log_record AFTER UPDATE OF status ON proposals WHEN NEW.status<>'pending' BEGIN INSERT INTO proposal_decision_log(proposal_id,project_id,actor_id,decision,digest,base_revision,created_at) VALUES(NEW.id,NEW.project_id,NEW.approved_by,NEW.status,NEW.digest,NEW.base_revision,NEW.decided_at); END;
